/* ---------- Buttons ---------- */
/* the button sheet: each style once, buttons with an icon, the states a button goes through and the three sizes, each row
   named on the left. A button is as wide as its words: when they change (Publishing, Copied, Running 0:03) it eases to the
   new width instead of keeping room for the longest (owner, 18 Nov), so its words never sit in empty space */
.btx{display:flex;flex-direction:column;gap:14px;width:100%}
.btx-row{display:flex;align-items:center;gap:var(--dm-s-2);flex-wrap:wrap}
.btx-l{width:74px;font-size:12px;flex:none}
@media (max-width:520px){.btx-l{width:100%}}
/* words on their way out while a button eases narrower stay inside it */
.btx-row .pill{overflow:hidden}
.btx-lg{height:40px;padding:0 18px;font-size:14px}
/* an icon button beside the pills is as tall as they are, so buttons side by side are one height */
.ib.btx-ib{width:32px;height:32px}
.btx-row .pill.btx-ok{cursor:default}
@media (hover:hover) and (pointer:fine){.btx-row .pill.btx-ok:hover{cursor:default}}
.btx-row .pill .spin{width:13px;height:13px}
.btx-row .pill.busy{cursor:progress}
/* Ask agent: a light sweeps across it under the pointer (not in Clean, whose hovers are a quiet fill); while the agent works it
   is the accent's tint with the shimmering words, as a highlight */
.btx-ask{position:relative;isolation:isolate}
.btx-ask::after{content:"";position:absolute;inset:0;background:linear-gradient(105deg,transparent 30%,rgba(255,255,255,.42) 50%,transparent 70%);transform:translateX(-120%);pointer-events:none}
.btx-ask:focus-visible::after{transform:translateX(120%);transition:transform .85s var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.btx-ask:hover::after{transform:translateX(120%);transition:transform .85s var(--dm-ease)}}
.btx-ask:is(.busy,.btx-ok)::after{display:none}
.pill.btx-ask.busy{background:var(--dm-accent-bg);color:var(--dm-accent-fg)}
@media (hover:hover) and (pointer:fine){.pill.btx-ask.busy:hover{background:var(--dm-accent-bg);color:var(--dm-accent-fg)}}
.btx-run .sq{width:9px;height:9px;border-radius:var(--dm-r-tiny,2px);background:currentColor;flex:none}
/* a button that has done its job (Published, Trial started, Run complete, Draft ready, Deleted) settles on the outlined face
   (it takes .line) with the vivid green tick in place of its icon, at the same size: no green fill (owner, 18 Nov). A copy or a
   menu pick says so the same way: the words stay in the text colour and only the tick is green */
.pill.btx-ok .i,.pill.btx-copy.copied .i{color:var(--dm-ok-mark)}
.pill.btx-copy.copied{color:var(--dm-fg)!important}
@media (hover:hover) and (pointer:fine){.pill.btx-copy.copied:hover{color:var(--dm-fg)!important}}
.ib.btx-ib.copied,.ib.btx-ib.done{color:var(--dm-ok-mark)!important}
@media (hover:hover) and (pointer:fine){.ib.btx-ib.copied:hover{color:var(--dm-ok-mark)!important}}
/* Preview is a toggle: on, it is the picked look (owner, 29 Oct), white with a slightly stronger grey edge, and a live dot */
.pill.btx-pv[aria-pressed="true"]{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line-strong) 55%,transparent)}
@media (hover:hover) and (pointer:fine){.pill.btx-pv[aria-pressed="true"]:hover{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line-strong) 55%,transparent)}}
.btx-live{position:relative;width:7px;height:7px;border-radius:50%;background:var(--dm-ok-mark);flex:none}
.btx-live::after{content:"";position:absolute;inset:0;border-radius:50%;background:inherit;animation:ping 1.8s var(--dm-ease) infinite}
/* a pill that swap() crossfades keeps its flex layout, so the icon put back in it later keeps its gap */
.btx-row .pill.sw{display:inline-flex}
.btx-sp{min-width:210px}
.btx-mp{min-width:200px}
.btx-mp .mi.del,.btx-mp .mi.del .i{color:var(--dm-bad)}
@media (hover:hover) and (pointer:fine){.btx-mp .mi.del:hover{background:var(--dm-bad-bg)}}
/* Hold to delete: the danger tint, filling from the left with the danger colour as it is held. The fill carries a white copy of
   the words, uncovered with it, so every letter reads on what is under it: red on the tint, white on the fill. Done, the fill
   fades and it is the outlined face with the green tick like the others */
.btx-hold{position:relative;overflow:hidden;background:var(--dm-bad-bg);color:var(--dm-bad);user-select:none;-webkit-user-select:none;touch-action:none}
.btx-hold .fill{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:var(--dm-bad);color:#fff;clip-path:inset(0 100% 0 0);transition:clip-path .25s var(--dm-ease),opacity var(--dm-t) var(--dm-ease);pointer-events:none}
.btx-hold.h .fill{clip-path:inset(0);transition:clip-path 1.2s linear}
.btx-hold .lb{position:relative;display:inline-flex;align-items:center;gap:7px;white-space:nowrap}
.btx-hold.btx-ok .fill{clip-path:inset(0);opacity:0}
/* in dark mode the danger text colour is a light pink, too light under white words, so the fill is the danger mark taken
   darker: white keeps 4.5:1 on it */
:root[data-theme="dark"] .btx-hold .fill{background:color-mix(in srgb,var(--dm-bad-mark) 70%,#000)}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .btx-hold .fill{background:color-mix(in srgb,var(--dm-bad-mark) 70%,#000)}}
/* Clean: secondary buttons are flat (owner, 18 Nov), so the icon buttons are too, with the hairline and white fill of the
   outlined pills beside them; Preview's on state is that face with a slightly stronger edge; while the agent works Ask agent is
   the flat face with its shimmering words, as the chrome stays monochrome; a done face (now .line) is flat and never presses */
:root[data-style="clean"] .ib.btx-ib.fill,:root [data-style="clean"] .ib.btx-ib.fill,:root [data-style="clean"].ib.btx-ib.fill{background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth);transition:box-shadow var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .ib.btx-ib.fill:hover,:root [data-style="clean"] .ib.btx-ib.fill:hover,:root [data-style="clean"].ib.btx-ib.fill:hover{box-shadow:var(--dm-btn2-hover)}}
:root[data-style="clean"] .ib.btx-ib.fill:active,:root [data-style="clean"] .ib.btx-ib.fill:active,:root [data-style="clean"].ib.btx-ib.fill:active{box-shadow:var(--dm-btn2-press)}
:root[data-style="clean"] .pill.soft.btx-pv[aria-pressed="true"]:not([disabled]),:root [data-style="clean"] .pill.soft.btx-pv[aria-pressed="true"]:not([disabled]),:root [data-style="clean"].pill.soft.btx-pv[aria-pressed="true"]:not([disabled]){background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line-strong) 55%,transparent)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .pill.soft.btx-pv[aria-pressed="true"]:not([disabled]):hover,:root [data-style="clean"] .pill.soft.btx-pv[aria-pressed="true"]:not([disabled]):hover,:root [data-style="clean"].pill.soft.btx-pv[aria-pressed="true"]:not([disabled]):hover{background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line-strong) 55%,transparent)}}
:root[data-style="clean"] .pill.btx-ask.busy:is(.primary,.accent):not([disabled]),:root [data-style="clean"] .pill.btx-ask.busy:is(.primary,.accent):not([disabled]),:root [data-style="clean"].pill.btx-ask.busy:is(.primary,.accent):not([disabled]){color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth);transform:none}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .pill.btx-ask.busy:is(.primary,.accent):not([disabled]):hover,:root [data-style="clean"] .pill.btx-ask.busy:is(.primary,.accent):not([disabled]):hover,:root [data-style="clean"].pill.btx-ask.busy:is(.primary,.accent):not([disabled]):hover{color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth);transform:none}}
:root[data-style="clean"] .btx-ask::after,:root [data-style="clean"] .btx-ask::after,:root [data-style="clean"].btx-ask::after{display:none}
:root[data-style="clean"] .pill.btx-ok:active,:root [data-style="clean"] .pill.btx-ok:active,:root [data-style="clean"].pill.btx-ok:active{transform:none}

DM.def('buttons', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{link}', I('link','s')).replace('{slack}', BRAND.slack).replace('{down}', I('down','s')).replace('{spark}', I('spark','xs')).replace('{figma}', I('figma','xs')).replace(/\{copy\}/g, (m, o) => I('copy','xs')).replace('{more}', I('more','xs')).replace(/\{trash\}/g, I('trash','xs')).replace('{bin}', I('trash','s')).replace('{dup}', I('copy','s')).replace('{edit}', I('edit','s')).replace('{folder}', I('folder','s'));
  /* a button is as wide as its words (owner, 18 Nov): when they change, whoever changes them (a click here, swap(), copied()),
     it eases from the width it showed to its new one, at the style's pace, instead of keeping room for its longest label */
  const cssV = v => getComputedStyle(r).getPropertyValue(v).trim();
  const ro = new ResizeObserver(es => es.forEach(e => { e.target._w = e.target.getBoundingClientRect().width; }));
  const mo = new MutationObserver(ms => new Set(ms.map(m => (m.target.nodeType === 1 ? m.target : m.target.parentElement).closest('.pill'))).forEach(b => {
    if (!b) return;
    const from = b._w; b.getAnimations().forEach(a => { if (a.id === 'fit') a.cancel(); });
    const to = b.getBoundingClientRect().width; b._w = to;
    if (REDUCE || !from || Math.abs(to - from) < .5) return;
    const s = cssV('--dm-t'), a = b.animate([{ width:from + 'px' }, { width:to + 'px' }], { duration:(s.endsWith('ms') ? parseFloat(s) : parseFloat(s) * 1000) || 340, easing:cssV('--dm-ease') || 'ease' }); a.id = 'fit';
  }));
  $$('.btx-row .pill', r).forEach(b => { b._w = b.getBoundingClientRect().width; ro.observe(b); mo.observe(b, { childList:true, characterData:true, subtree:true }); });
  c.offs.push(() => { ro.disconnect(); mo.disconnect(); });
  /* done: the outlined face with the vivid green tick in place of the icon, at the same size, and no green fill (owner, 18 Nov);
     undone() puts back the face it had */
  const done = (b, words, el = b) => {
    if (!b._was){ b._was = ['primary', 'accent', 'soft'].find(k => b.classList.contains(k)) || (b.classList.contains('line') ? '-' : '+'); if (b._was !== '-'){ if (b._was !== '+') b.classList.remove(b._was); b.classList.add('line'); } }
    b.classList.add('btx-ok'); el.innerHTML = I('check','xs') + words; enter(el.firstChild);
  };
  const undone = b => { b.classList.remove('btx-ok'); if (b._was && b._was !== '-'){ b.classList.remove('line'); if (b._was !== '+') b.classList.add(b._was); } b._was = null; };
  const ld = $('.btx-load', r);
  /* busy buttons keep their colour; disabled styling is only for buttons you can't use */
  ld.onclick = () => c.run(async () => { if (ld._busy) return; ld._busy = true; ld.classList.add('busy'); ld.setAttribute('aria-busy', 'true'); ld.innerHTML = '<span class="spin"></span>Publishing'; await c.wait(1300); ld.classList.remove('busy'); ld.removeAttribute('aria-busy'); done(ld, 'Published'); await c.wait(1800); undone(ld); ld.textContent = 'Publish'; ld._busy = false; });
  const ask = $('.btx-ask', r);
  ask.onclick = () => c.run(async () => { if (ask._busy) return; ask._busy = true; ask.classList.add('busy'); ask.setAttribute('aria-busy', 'true'); ask.innerHTML = '<span class="think on"><i></i><i></i><i></i><i></i></span><span class="shim">Agent is working</span>';
    await c.wait(2200); ask.classList.remove('busy'); ask.removeAttribute('aria-busy'); done(ask, 'Draft ready');
    await c.wait(1800); undone(ask); ask.innerHTML = I('spark','xs') + 'Ask agent'; ask._busy = false; });
  const icp = $('.btx-icp', r); icp.onclick = () => copied(icp, 'https://designme.dev/p/pricing');
  /* Start free trial: a short wait, then a confirmed state */
  const tr = $('.btx-trial', r);
  tr.onclick = () => c.run(async () => { if (tr._busy) return; tr._busy = true; tr.classList.add('busy'); tr.setAttribute('aria-busy', 'true'); tr.innerHTML = '<span class="spin"></span>Starting'; await c.wait(1100); tr.classList.remove('busy'); tr.removeAttribute('aria-busy'); done(tr, 'Trial started'); await c.wait(1800); undone(tr); swap(tr, 'Start free trial'); tr._busy = false; });
  /* Run agent: shows the run time, turns into Stop while you hover it. Stop keeps the running width, so the button never
     narrows away from the pointer on it */
  const rn = $('.btx-run', r); let rt = 0, rtick = null, rdone = null;
  const idle = () => { clearInterval(rtick); clearTimeout(rdone); rn.classList.remove('busy'); rn.removeAttribute('aria-busy'); rn.style.minWidth = ''; rn._run = false; };
  const rlabel = () => { if (!rn._run) return; const stop = rn.matches(':hover'); rn.style.minWidth = stop ? rn.getBoundingClientRect().width + 'px' : ''; rn.innerHTML = stop ? '<span class="sq"></span>Stop' : `<span class="spin"></span>Running <span class="num">${Math.floor(rt / 60)}:${String(rt % 60).padStart(2, '0')}</span>`; };
  rn.onclick = () => {
    if (rn._run){ idle(); rn.innerHTML = '<span class="sq"></span>Stopped'; c.later(1200, () => { if (!rn._run) swap(rn, 'Run agent'); }); return; }
    undone(rn); rn._run = true; rt = 0; rn.classList.add('busy'); rn.setAttribute('aria-busy', 'true'); rlabel();
    rtick = setInterval(() => { rt++; rlabel(); }, 1000);
    rdone = setTimeout(() => { idle(); done(rn, 'Run complete'); c.later(1800, () => { if (!rn._run){ undone(rn); swap(rn, 'Run agent'); } }); }, 3200);
  };
  rn.onmouseenter = rlabel; rn.onmouseleave = rlabel;
  c.offs.push(idle);
  /* Preview: a toggle, live while it is on */
  const pv = $('.btx-pv', r);
  pv.onclick = () => { const on = pv.getAttribute('aria-pressed') !== 'true'; pv.setAttribute('aria-pressed', on); pv.innerHTML = on ? '<span class="btx-live"></span>Previewing' : 'Preview'; };
  /* Share: a small menu, the button says what happened */
  const sh = $('.btx-share', r);
  const said = (t, ms = 1600) => { done(sh, t); clearTimeout(sh._t); sh._t = setTimeout(() => { undone(sh); swap(sh, 'Share'); }, ms); };
  $$('.btx-sp .mi', r).forEach(b => b.addEventListener('click', () => {
    const a = b.dataset.a;
    if (a === 'link'){ try { navigator.clipboard.writeText('https://designme.dev/p/pricing').catch(() => {}); } catch(e){} said('Link copied'); }
    else if (a === 'slack') said('Sent to #design');
    else { clearTimeout(sh._t); undone(sh); sh.innerHTML = '<span class="spin"></span>Exporting'; sh._t = setTimeout(() => said('PDF ready'), 1100); }
  }));
  c.offs.push(() => clearTimeout(sh._t));
  /* Open in Figma: a short wait while it opens, then it says where it went */
  const fg = $('.btx-fig', r);
  fg.onclick = () => c.run(async () => { if (fg._busy) return; fg._busy = true; fg.classList.add('busy'); fg.setAttribute('aria-busy', 'true'); fg.innerHTML = '<span class="spin"></span>Opening'; await c.wait(900);
    fg.classList.remove('busy'); fg.innerHTML = I('ext','xs') + 'Opened in Figma'; enter(fg.firstChild); await c.wait(1800); swap(fg, I('figma','xs') + 'Open in Figma', true); await c.wait(200); fg._busy = false; fg.removeAttribute('aria-busy'); });
  /* More: a menu of actions; the button flashes the green tick and says what happened */
  const mo2 = $('.btx-more', r), moIc = mo2.innerHTML;
  // no tooltip over its own open menu
  const mob = new MutationObserver(() => { if (mo2.getAttribute('aria-expanded') === 'true'){ if (tipFor === mo2) hideTip(true); delete mo2.dataset.tip; } else if (!mo2.classList.contains('done')) mo2.dataset.tip = 'More'; });
  mob.observe(mo2, { attributes:true, attributeFilter:['aria-expanded'] }); c.offs.push(() => mob.disconnect());
  $$('.btx-mp .mi', r).forEach(b => b.addEventListener('click', () => {
    clearTimeout(mo2._t); c.later(140, () => { mo2.innerHTML = I('check','xs'); mo2.classList.add('done'); mo2.dataset.tip = b.dataset.a; showTip(mo2);
      mo2._t = setTimeout(() => { mo2.innerHTML = moIc; mo2.classList.remove('done'); mo2.dataset.tip = 'More'; if (tipFor === mo2) hideTip(true); }, 1500); });
  }));
  c.offs.push(() => clearTimeout(mo2._t));
  const cp = $('.btx-copy', r);
  cp.onclick = () => { copied(cp, 'https://designme.dev/p/pricing'); const t = cp.lastChild; t.textContent = 'Copied'; clearTimeout(cp._lt); cp._lt = setTimeout(() => { t.textContent = 'Copy link'; }, 1600); };
  // its words, and their white copy on the fill, change together
  const h = $('.btx-hold', r), lbs = $$('.lb', h), lb = lbs[0], words = html => lbs.forEach(l => { l.innerHTML = html; }); let t;
  // the label crossfades to Keep holding by hand, so an early release can cancel it before the text lands
  const start = e => { if (h.classList.contains('btx-ok')) return; h.classList.add('h'); lbs.forEach(l => l.classList.add('sw', 'out')); clearTimeout(h._sw); h._sw = setTimeout(() => { words('Keep holding'); lbs.forEach(l => l.classList.remove('out')); }, REDUCE ? 0 : 170); t = setTimeout(() => { h.classList.remove('h'); done(h, 'Deleted', lb); lbs[1].innerHTML = lb.innerHTML; c.later(1800, () => { undone(h); words(I('trash','xs') + 'Hold to delete'); }); }, 1200); };
  const end = () => { if (!h.classList.contains('h')) return; clearTimeout(t); clearTimeout(h._sw); lbs.forEach(l => l.classList.remove('out')); h.classList.remove('h'); words(I('trash','xs') + 'Hold to delete'); };
  h.onpointerdown = start; h.onpointerup = end; h.onpointerleave = end;
  h.onkeydown = e => { if ((e.key === ' ' || e.key === 'Enter') && !e.repeat){ e.preventDefault(); start(); } };
  h.onkeyup = e => { if (e.key === ' ' || e.key === 'Enter') end(); }; h.onblur = end;
  c.offs.push(() => { clearTimeout(t); clearTimeout(h._sw); });
});
